import{_ as r,o as s,c as o,a2 as a}from"./chunks/framework.YT-FC_Xx.js";const p=JSON.parse('{"title":"服务器设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/servers.md","filePath":"guide/servers.md","lastUpdated":1794151265000}'),n={name:"guide/servers.md"};function e(g,t,l,i,d,h){return s(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="服务器设置" tabindex="-1">服务器设置 <a class="header-anchor" href="#服务器设置" aria-label="Permalink to &quot;服务器设置&quot;">​</a></h1><p><strong>服务器</strong> 页点一台服务器 → <strong>编辑</strong>，设置分成几块：基本、价格与到期、流量、地址与地区、转发方式，不常用的通知和高级选项折叠在最下面。</p><h2 id="基本" tabindex="-1">基本 <a class="header-anchor" href="#基本" aria-label="Permalink to &quot;基本&quot;">​</a></h2><ul><li><strong>名称</strong>、<strong>分组</strong>：分组随便填，例如「香港」「家宽」「主力」，已用过的分组会列在输入框下面，点一下就能填上。服务器列表上方可以按分组筛选，状态页也可以按分组显示，见 <a href="./status-page">状态页</a></li><li><strong>公开备注</strong>：显示在状态页的服务器名称下面，最多 200 字</li><li><strong>私有备注</strong>：只有管理员看得到</li><li><strong>公开显示</strong>：关闭后这台服务器不出现在状态页上，和 <strong>设置 → 状态页 → 显示哪些服务器</strong> 是同一个设置</li><li><strong>离线通知</strong>：服务器掉线、恢复时各推一条，需要先在 <strong>设置 → 通知</strong> 打开通知；其他事件在下面的 <strong>通知</strong> 里单独设置</li></ul><h2 id="价格与到期" tabindex="-1">价格与到期 <a class="header-anchor" href="#价格与到期" aria-label="Permalink to &quot;价格与到期&quot;">​</a></h2><p>填 <strong>价格</strong>、<strong>货币</strong>、<strong>付款周期</strong>（例如「1 年」「3 月」）和 <strong>到期时间</strong>。到期时间过了以后，面板按付款周期自动顺延到下一次，快到期时按 <strong>设置 → 通知</strong> 里的到期提醒推送。价格留空或填 0 表示免费；付款周期和到期时间要一起填。</p><p>续费后只想改价格或到期时间时，在服务器上点 <strong>价格与到期</strong>，会打开一个只有这几项的小窗口。</p><p>状态页默认不显示价格，在 <strong>设置 → 状态页</strong> 打开 <strong>显示价格</strong> 后才显示，例如 <code>¥151.2/年</code>。</p><h2 id="流量额度与校正" tabindex="-1">流量额度与校正 <a class="header-anchor" href="#流量额度与校正" aria-label="Permalink to &quot;流量额度与校正&quot;">​</a></h2><ul><li><strong>每月额度（GB）</strong>：留空不限。设了以后，服务器列表上显示「已用 / 额度」，快用完时变色；状态页上有额度进度条</li><li><strong>计算方式</strong>：上下行相加、取较大值、只算上行（服务器发出的）或只算下行（服务器收到的），按服务商的计费方式选</li><li><strong>每月重置日</strong>：1–31，默认 1 号。本月流量从这一天 0 点开始算（按面板所在时区）；月份没有这一天时（例如 31 号遇到 2 月）按月底</li></ul><p>服务器列表和状态页的「本月」流量都按这里的重置日计算。</p><p><strong>流量校正</strong>：面板统计和服务商面板上的用量对不上时，展开 <strong>流量校正</strong>，填服务商显示的本期上行、下行（GB），保存后本期流量就改成这个数，之后照常累加。只改其中一项时另一项留空。校正只对本期有效，到下一个重置日自动失效。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>3.9.4 之前的 agent 会把 Docker、虚拟网卡的流量也算进去，容器重启时还可能把开机以来的总流量重复加一遍，导致「本月流量」偏大很多。升级 agent 后不会再这样；已经多算的部分用流量校正改回来即可。</p></div><h2 id="地址与地区" tabindex="-1">地址与地区 <a class="header-anchor" href="#地址与地区" aria-label="Permalink to &quot;地址与地区&quot;">​</a></h2><p>至少填一个 <strong>IPv4</strong>、<strong>IPv6</strong> 或 <strong>域名</strong>，这是这台服务器自己的地址（不是面板的地址），分享节点、对接中转时用它。<strong>国家/地区</strong> 默认按地址自动识别，也可以手动选，见 <a href="./status-page#地区">状态页 → 地区</a>。<strong>可用端口</strong> 是面板分配给转发和节点用的端口范围。</p><h2 id="转发方式" tabindex="-1">转发方式 <a class="header-anchor" href="#转发方式" aria-label="Permalink to &quot;转发方式&quot;">​</a></h2><ul><li><strong>agent</strong>（推荐）：服务器安装 agent，支持全部功能，见 <a href="./agent">安装 agent</a></li><li><strong>nftables</strong>：不装 agent，面板通过 SSH 下发 nftables 规则，只能做纯端口转发；选它以后在下面填 SSH 主机、用户名和认证方式</li></ul>',17)])])}const u=r(n,[["render",e]]);export{p as __pageData,u as default};
